<script lang="ts">
  import { onMount } from 'svelte';
  import { api } from '$lib/api';

  type PortalStudent = { studentId: number; firstName: string; lastName: string; displayName: string; nickname?: string; pronouns?: string; honorific?: string; roles?: string[]; rankName?: string; rankAwardedDate?: string; rankNotes?: string; ageGroup?: string; birthDate?: string; isActive: boolean; status: 'active' | 'paused' | 'deactivated'; joinDate?: string; uniformSize?: string; beltSize?: string; bio?: string; favoriteTechnique?: string; totalClasses: number; helperClasses: number; attendanceStreak: number; achievementCount: number; goldStarCount: number; programs: string[] };
  type Rank = { rankId: number; name: string; sortOrder: number; displayColor?: string | null; isActive: boolean; studentCount: number };
  type Program = { programId: number; name: string; description?: string | null };
  type StudentForm = { firstName: string; lastName: string; preferredName: string; nickname: string; pronouns: string; honorific: string; ageGroup: string; birthDate: string; joinDate: string; uniformSize: string; beltSize: string; bio: string; favoriteTechnique: string; rankId: string; rankAwardedDate: string; rankNotes: string; programIds: string[] };
  const blankForm = (): StudentForm => ({ firstName: '', lastName: '', preferredName: '', nickname: '', pronouns: '', honorific: '', ageGroup: 'Kids', birthDate: '', joinDate: new Date().toISOString().slice(0, 10), uniformSize: '', beltSize: '', bio: '', favoriteTechnique: '', rankId: '', rankAwardedDate: new Date().toISOString().slice(0, 10), rankNotes: '', programIds: [] });
  let students: PortalStudent[] = [];
  let ranks: Rank[] = [];
  let programs: Program[] = [];
  let form = blankForm();
  let selectedRoles = ['student'];
  let originalRankId = '';
  let originalRankAwardedDate = '';
  let originalRankNotes = '';
  let originalProgramNames: string[] = [];
  let editingId = '';
  let showForm = false;
  let statusFilter: 'active' | 'paused' | 'deactivated' | 'all' = 'active';
  let query = '';
  let page = 1;
  const pageSize = 25;
  let error = '';
  let notice = '';
  let loading = true;
  let saving = false;
  let resettingPin = false;
  let pinForm = { pin: '', confirmPin: '' };

  async function load() { loading = true; error = ''; try { [students, ranks, programs] = await Promise.all([api<PortalStudent[]>('/api/portal-admin/students'), api<Rank[]>('/api/portal-admin/configuration/ranks'), api<Program[]>('/api/portal-admin/programs')]); } catch (e) { error = e instanceof Error ? e.message : 'Could not load portal students.'; } finally { loading = false; } }
  $: visibleStudents = students.filter((student) => (statusFilter === 'all' || student.status === statusFilter) && `${student.displayName} ${student.nickname ?? ''} ${student.pronouns ?? ''} ${student.rankName ?? ''} ${student.programs.join(' ')}`.toLowerCase().includes(query.trim().toLowerCase()));
  $: orderedRanks = [...ranks].sort((a, b) => rankSortKey(a) - rankSortKey(b) || a.name.localeCompare(b.name));
  $: pageCount = Math.max(1, Math.ceil(visibleStudents.length / pageSize));
  $: if (page > pageCount) page = pageCount;
  $: pagedStudents = visibleStudents.slice((page - 1) * pageSize, page * pageSize);
  $: editingStudent = editingId ? students.find((student) => String(student.studentId) === editingId) : null;
  function resetPage() { page = 1; }
  function previousPage() { if (page > 1) page -= 1; }
  function nextPage() { if (page < pageCount) page += 1; }
  function fullName(student: PortalStudent) { return `${student.firstName} ${student.lastName}`.trim(); }
  function rankSortKey(rank: Rank) { const name = rank.name.toLowerCase(); const beltOrder = ['white', 'yellow', 'orange', 'green', 'purple', 'blue', 'red', 'brown', 'black']; const beltIndex = beltOrder.findIndex((belt) => name.includes(belt)); const degree = Number(name.match(/(\d+)(?:st|nd|rd|th)?\s+degree/)?.[1] ?? 0); return (beltIndex < 0 ? 10000 : beltIndex * 100) + (beltIndex === 8 ? degree || 0 : 0); }
  function programLabel(program: Program) { return program.name.replace(/\s*�\s*/g, ' • '); }
  function resetForm() { form = blankForm(); selectedRoles = ['student']; originalRankId = ''; originalRankAwardedDate = ''; originalRankNotes = ''; originalProgramNames = []; editingId = ''; showForm = false; }
  function addStudent() { form = blankForm(); selectedRoles = ['student']; originalRankId = ''; originalRankAwardedDate = ''; originalRankNotes = ''; originalProgramNames = []; editingId = ''; showForm = true; window.scrollTo({ top: 0, behavior: 'smooth' }); }
  function edit(student: PortalStudent) { editingId = String(student.studentId); showForm = true; const rankId = ranks.find((rank) => rank.name === student.rankName)?.rankId.toString() ?? ''; originalRankId = rankId; originalRankAwardedDate = student.rankAwardedDate?.slice(0, 10) ?? ''; originalRankNotes = student.rankNotes ?? ''; originalProgramNames = [...student.programs]; selectedRoles = student.roles?.length ? student.roles : ['student']; form = { ...blankForm(), firstName: student.firstName, lastName: student.lastName, preferredName: '', nickname: student.nickname ?? '', pronouns: student.pronouns ?? '', honorific: student.honorific ?? '', ageGroup: student.ageGroup === 'TeensAdults' ? 'TeensAdults' : 'Kids', birthDate: student.birthDate?.slice(0, 10) ?? '', joinDate: student.joinDate?.slice(0, 10) ?? blankForm().joinDate, uniformSize: student.uniformSize ?? '', beltSize: student.beltSize ?? '', bio: student.bio ?? '', favoriteTechnique: student.favoriteTechnique ?? '', rankAwardedDate: student.rankAwardedDate?.slice(0, 10) ?? blankForm().rankAwardedDate, rankNotes: student.rankNotes ?? '', rankId, programIds: programs.filter((program) => student.programs.includes(program.name)).map((program) => String(program.programId)) }; window.scrollTo({ top: 0, behavior: 'smooth' }); }
  function toggleRole(role: string, enabled: boolean) { selectedRoles = enabled ? [...new Set([...selectedRoles, role])] : selectedRoles.filter((item) => item !== role); if (!selectedRoles.includes('student')) selectedRoles = ['student', ...selectedRoles]; }
  function programCode(program: Program) { return program.name === 'Kids' ? 'kids' : program.name === 'Teen/Adult' ? 'teen-adult' : program.name === 'IS3' ? 'is3' : `program-${program.programId}`; }
  async function syncPrograms(studentId: number) { const selected = new Set(form.programIds); const existing = new Set(originalProgramNames); for (const program of programs) { const isSelected = selected.has(String(program.programId)); const wasSelected = existing.has(program.name); if (isSelected && !wasSelected) await api(`/api/portal-admin/students/${studentId}/programs`, { method: 'POST', body: JSON.stringify({ programId: program.programId, progressionType: program.name.toLowerCase().includes('is3') ? 'level' : 'belt' }) }); if (!isSelected && wasSelected) await api(`/api/portal-admin/students/${studentId}/programs/${encodeURIComponent(programCode(program))}`, { method: 'DELETE' }); } }
  async function save() { error = ''; notice = ''; saving = true; try { const payload = { ...form, roles: selectedRoles, preferredName: form.nickname || form.preferredName, birthDate: form.birthDate || null, joinDate: form.joinDate || null }; let studentId = Number(editingId); if (editingId) { await api(`/api/portal-admin/students/${editingId}`, { method: 'PUT', body: JSON.stringify(payload) }); notice = 'Student profile updated in the portal database.'; } else { const result = await api<{ id: number }>('/api/portal-admin/students', { method: 'POST', body: JSON.stringify(payload) }); studentId = result.id; notice = 'Portal student created.'; } const rankChanged = form.rankId !== originalRankId || form.rankAwardedDate !== originalRankAwardedDate || form.rankNotes.trim() !== originalRankNotes.trim(); if (rankChanged && (form.rankId || originalRankId)) { await api(`/api/portal-admin/students/${studentId}/rank`, { method: 'POST', body: JSON.stringify({ rankId: Number(form.rankId || 0), awardedDate: form.rankAwardedDate || null, notes: form.rankNotes.trim() || null }) }); notice = `${notice} Belt rank recorded.`; } await syncPrograms(studentId); if (form.programIds.length) notice = `${notice} Program memberships updated.`; resetForm(); await load(); } catch (e) { error = e instanceof Error ? e.message : 'Could not save student.'; } finally { saving = false; } }
  async function setStatus(student: PortalStudent, status: 'active' | 'paused' | 'deactivated') { error = ''; try { await api(`/api/portal-admin/students/${student.studentId}/status`, { method: 'POST', body: JSON.stringify({ status }) }); notice = `${student.displayName} marked ${status}.`; await load(); } catch (e) { error = e instanceof Error ? e.message : 'Could not update student status.'; } }
  async function setPin() { if (!editingId) return; error = ''; notice = ''; resettingPin = true; try { const result = await api<{ username: string }>(`/api/portal-admin/students/${editingId}/pin`, { method: 'POST', body: JSON.stringify(pinForm) }); pinForm = { pin: '', confirmPin: '' }; notice = `Student PIN saved for ${result.username}. It now works for Hub access and class check-in.`; } catch (e) { error = e instanceof Error ? e.message : 'Could not save the student PIN.'; } finally { resettingPin = false; } }
  onMount(load);
</script>

<svelte:head><title>Staff · Students | Task Karate</title></svelte:head>

<div class="toolbar"><div><span class="eyebrow">PORTAL PEOPLE</span><h2>Student profiles</h2><p class="muted">This roster reads and writes the same database used by the student hub. Changes are audited.</p></div><div class="toolbar-actions"><button class="button" type="button" on:click={addStudent}>Add student</button></div></div>
{#if error}<div class="error" role="alert">{error}</div>{/if}{#if notice}<div class="status" role="status">{notice}</div>{/if}

{#if showForm}
  <section class="card">
    <div class="section-heading"><div><h3>{editingId ? `Edit ${form.firstName} ${form.lastName}` : 'Add a student'}</h3><p class="muted">Keep identity and dojo details current. The full name is shown here so staff can distinguish students with the same nickname or honorific.</p></div><button class="button secondary small-button" type="button" on:click={resetForm}>Close</button></div>
    <form class="form-grid" on:submit|preventDefault={save}>
      <label>First name<input bind:value={form.firstName} required /></label>
      <label>Last name<input bind:value={form.lastName} required /></label>
      <label>Nickname <small class="muted">optional</small><input bind:value={form.nickname} placeholder="What they like to be called" /></label>
      <label>Pronouns <small class="muted">optional</small><input bind:value={form.pronouns} placeholder="e.g. she/her, they/them" /></label>
      <label>Honorific <small class="muted">for black belt addressing</small><select bind:value={form.honorific}><option value="">No title set</option><option>Mr.</option><option>Mrs.</option><option>Ms.</option><option>Mx.</option><option>Dr.</option></select></label>
      <fieldset class="full student-role-fieldset"><legend>Dojo roles & responsibilities</legend><p class="muted">These roles stay on the student record so the same person can be a student and help run the dojo. Staff login access is managed separately from Staff access.</p><div class="student-role-grid">{#each [{ id: 'student', label: 'Student' }, { id: 'assistant_instructor', label: 'Assistant instructor' }, { id: 'instructor', label: 'Instructor' }, { id: 'news_admin', label: 'News admin' }] as role}<label class="check-row"><input type="checkbox" checked={selectedRoles.includes(role.id)} disabled={role.id === 'student'} on:change={(event) => toggleRole(role.id, (event.currentTarget as HTMLInputElement).checked)} />{role.label}</label>{/each}</div></fieldset>
      <label>Program age group<select bind:value={form.ageGroup}><option value="Kids">Kids</option><option value="TeensAdults">Teens / Adults</option></select></label>
      <fieldset class="full student-role-fieldset"><legend>Program memberships</legend><p class="muted">Select every program this student participates in. A student can belong to more than one program.</p><div class="student-role-grid">{#each programs as program}<label class="check-row"><input type="checkbox" checked={form.programIds.includes(String(program.programId))} on:change={(event) => { const id = String(program.programId); form = { ...form, programIds: (event.currentTarget as HTMLInputElement).checked ? [...new Set([...form.programIds, id])] : form.programIds.filter((item) => item !== id) }; }} />{programLabel(program)}</label>{/each}</div></fieldset>
      <fieldset class="full student-role-fieldset student-metrics-fieldset"><legend>Attendance & recognition</legend><p class="muted">These totals are calculated from attendance and recognition records, so they stay accurate instead of becoming hand-entered counters.</p><div class="student-metrics-grid"><div><strong>{editingStudent?.totalClasses ?? 0}</strong><span>Classes attended</span></div><div><strong>{editingStudent?.helperClasses ?? 0}</strong><span>Classes helped</span></div><div><strong>{editingStudent?.attendanceStreak ?? 0}</strong><span>Attendance streak</span></div><div><strong>{editingStudent?.achievementCount ?? 0}</strong><span>Achievements</span></div><div><strong>{editingStudent?.goldStarCount ?? 0}</strong><span>Gold Stars</span></div></div>{#if editingId}<div class="table-actions"><a class="button secondary small-button" href={`/staff/attendance?studentId=${editingId}`}>Manage attendance</a><a class="button secondary small-button" href={`/staff/awards?studentId=${editingId}`}>Manage recognition</a></div>{:else}<small class="muted">Save the student first, then attendance and recognition can be recorded against this profile.</small>{/if}</fieldset>
      <label>Date of birth<input type="date" bind:value={form.birthDate} /></label>
      <label>Member since<input type="date" bind:value={form.joinDate} required /></label>
      <label>Uniform size<input bind:value={form.uniformSize} /></label>
      <label>Belt size<input bind:value={form.beltSize} /></label>
      <label>Belt rank<select bind:value={form.rankId}><option value="">No rank assigned yet</option>{#each orderedRanks.filter((rank) => rank.isActive) as rank}<option value={rank.rankId}>{rank.name}</option>{/each}</select><small class="muted">Ranks are ordered from beginner belts through black belt degrees.</small></label>
      <label>Rank awarded date<input type="date" bind:value={form.rankAwardedDate} disabled={!form.rankId} /></label>
      <label class="full">Rank note <small class="muted">optional</small><input bind:value={form.rankNotes} disabled={!form.rankId} placeholder="Instructor or promotion context" /></label>
      <label class="full">Short bio<textarea bind:value={form.bio} rows="2"></textarea></label>
      <label class="full">Favorite technique<input bind:value={form.favoriteTechnique} /></label>
      <div class="full"><button class="button" disabled={saving}>{saving ? 'Saving…' : 'Save student record'}</button></div>
    </form>
  </section>
  {#if editingId}<section class="card password-admin-card"><div class="section-heading"><div><h3>Student PIN</h3><p class="muted">One 4–6 digit PIN handles both Student Hub access and supervised class check-in.</p></div></div><form class="form-grid" on:submit|preventDefault={setPin}><label>New student PIN<input type="password" bind:value={pinForm.pin} inputmode="numeric" minlength="4" maxlength="6" pattern="[0-9][0-9][0-9][0-9][0-9]?[0-9]?" autocomplete="new-password" required /><small class="muted">Give the student one PIN to use in both places.</small></label><label>Confirm student PIN<input type="password" bind:value={pinForm.confirmPin} inputmode="numeric" minlength="4" maxlength="6" pattern="[0-9][0-9][0-9][0-9][0-9]?[0-9]?" autocomplete="new-password" required /></label><div class="full"><button class="button" disabled={resettingPin}>{resettingPin ? 'Saving…' : 'Save student PIN'}</button></div></form></section>{/if}
{/if}

<section class="card"><div class="section-heading"><div><h3>{statusFilter === 'all' ? 'All portal records' : `${statusFilter[0].toUpperCase()}${statusFilter.slice(1)} portal roster`}</h3><span class="pill">{visibleStudents.length}</span></div><div class="staff-list-controls"><input bind:value={query} on:input={resetPage} type="search" placeholder="Search portal students…" aria-label="Search portal students" /><label>Status<select bind:value={statusFilter} on:change={resetPage}><option value="active">Active</option><option value="paused">Paused</option><option value="deactivated">Deactivated</option><option value="all">All statuses</option></select></label></div></div><p class="muted roster-help">Active students can be enrolled and checked in. Paused students remain in the portal directory but are hidden from attendance pickers. Deactivated records are retained for history.</p>{#if loading}<p class="muted">Loading portal database…</p>{:else}<div class="table-wrap"><table><thead><tr><th>Student</th><th>Programs</th><th>Classes</th><th>Recognition</th><th>Status</th><th>Actions</th></tr></thead><tbody>{#each pagedStudents as student}<tr><td><a class="staff-record-link" href={`/staff/students/${student.studentId}`}><strong>{fullName(student)}</strong></a><small class="table-subtext">{student.displayName !== fullName(student) ? `Portal name: ${student.displayName} · ` : ''}{student.rankName ?? 'Rank not assigned'} · {student.pronouns ?? 'Pronouns not set'} · {student.ageGroup ?? 'Age group not set'}{student.birthDate ? ` · DOB ${student.birthDate.slice(0, 10)}` : ''}</small></td><td>{student.programs.join(', ') || 'No program'}</td><td>{student.totalClasses} attended · {student.helperClasses} helped · {student.attendanceStreak} day streak</td><td>{student.achievementCount} achievements · {student.goldStarCount} Gold Stars</td><td><span class="pill student-status-pill {student.status}">{student.status === 'active' ? 'Active' : student.status === 'paused' ? 'Paused' : 'Deactivated'}</span></td><td><div class="table-actions"><a class="button secondary small-button" href={`/staff/students/${student.studentId}`}>Open record</a><button class="button secondary small-button" type="button" on:click={() => edit(student)}>Edit profile</button>{#if student.status === 'active'}<button class="button secondary small-button" type="button" on:click={() => setStatus(student, 'paused')}>Pause student</button><button class="button danger small-button" type="button" on:click={() => setStatus(student, 'deactivated')}>Deactivate</button>{:else if student.status === 'paused'}<button class="button secondary small-button" type="button" on:click={() => setStatus(student, 'active')}>Resume student</button><button class="button danger small-button" type="button" on:click={() => setStatus(student, 'deactivated')}>Deactivate</button>{:else}<button class="button secondary small-button" type="button" on:click={() => setStatus(student, 'active')}>Reactivate</button>{/if}</div></td></tr>{:else}<tr><td colspan="6" class="muted">No portal students match this view.</td></tr>{/each}</tbody></table></div><div class="pagination" aria-label="Student roster pages"><button class="button secondary small-button" type="button" disabled={page <= 1} on:click={previousPage}>Previous</button><span>Page {page} of {pageCount}</span><button class="button secondary small-button" type="button" disabled={page >= pageCount} on:click={nextPage}>Next</button></div>{/if}</section>
